/* ======================================= */
/* 1. БЛОК ПЕРЕМЕННЫХ (Variables) */
/* ======================================= */
:root {
	/* Fonts */
	--font-family: 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;

	/* Typography */
	--font-size-label: 16px;
	--font-size-header: 24px;
	--font-size-subheader: 14px;
	--font-size-paragraph: 14px;
	--font-size-details: 12px;
	--font-size-error: 13px;

	/* Colors — Telegram style */
	--color-background: #f1f6fb;
	--color-header-bg: #229ED9; /* Telegram Blue */
	--color-header-text: #ffffff; /* Белый цвет */
	--color-card-bg: #ffffff;
	--color-card-shadow: rgba(34, 158, 217, 0.15);
	--color-label: #2b2b2b;
	--color-details: #5b6c7b;
	--color-input-border: #cfd8e6;
	--color-focus-border: #229ED9; 
	--color-submit-btn-bg: #229ED9;
	--color-submit-btn-text: #ffffff;
	--color-error: #ea1f30;

	/* Border Radii */
	--border-radius-card: 16px; 
	--border-radius-input: 10px;

	/* Spacing */
	--submit-btn-height: 48px;
	--checkbox-size: 20px;
    --padding-sides: 32px; /* Отступы по бокам для контента */

    --container-width: 620px;
}

/* ======================================= */
/* 2. ОСНОВНАЯ СТИЛИЗАЦИЯ КАРТОЧКИ И ШАПКИ */
/* ======================================= */

.card {
    padding: 0; 
    box-shadow: 0px 8px 25px 0px var(--color-card-shadow);
    border-radius: var(--border-radius-card);
    overflow: hidden;
    background-color: var(--color-card-bg);
    font-family: var(--font-family);
}

.form-header {
    position: relative;
    background: var(--color-header-bg); 
    /* Текст должен быть белым, но мы добавим его для h1 и p отдельно, чтобы гарантировать это */
    color: var(--color-header-text) !important; /* Устанавливаем белый для всего блока */

    padding: 25px var(--padding-sides);
    border-top-left-radius: var(--border-radius-card);
    border-top-right-radius: var(--border-radius-card);
    text-align: center;
}

.form-header h1 {
    font-size: var(--font-size-header);
    font-weight: var(--font-weight-bold);
    margin: 0 0 5px 0;
    line-height: 1.2;
    /* ГАРАНТИЯ БЕЛОГО ЦВЕТА */
    color: var(--color-header-text) !important; 
}

.form-header p {
    font-size: var(--font-size-subheader);
    opacity: 0.9;
    margin: 0;
    /* ГАРАНТИЯ БЕЛОГО ЦВЕТА */
    color: var(--color-header-text) !important; 
}

/* ======================================= */
/* 3. INPUTS-WRAPPER (Секция с полями) */
/* ======================================= */

.form-header::before {
  content: "";
  position: absolute;
  left: 20px;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;

  background-image: url("https://cdn-icons-png.flaticon.com/512/2111/2111646.png");
  background-size: 80%; /* иконка чуть меньше внутри */
  background-repeat: no-repeat;
  background-position: center;

  background-color: #ffffff;   /* белый фон */
  border-radius: 50%;          /* кружок */
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.2); /* лёгкая тень вместо толстой рамки */
}

.inputs-wrapper {
    margin: 30px var(--padding-sides) 20px var(--padding-sides);
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 24px; /* равномерные промежутки между группами полей */
}

.form-label {
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-bold);
    margin-bottom: 6px; /* меньшее расстояние между label и полем */
    color: var(--color-label);
}

.multiselect {
    position: relative;
    border: 1px solid var(--color-input-border);
    border-radius: var(--border-radius-input);
    background-color: #ffffff;
    box-shadow: 0 3px 8px rgba(34, 158, 217, 0.1);
    overflow: hidden;
    transition: all 0.2s ease;
}

.multiselect:hover {
    border-color: var(--color-focus-border);
    box-shadow: 0 4px 12px rgba(34, 158, 217, 0.15);
}

/* Вариант открытого списка — если у тебя есть класс .open */
.multiselect.open {
    border-color: var(--color-focus-border);
    box-shadow: 0 6px 16px rgba(34, 158, 217, 0.2);
}

/* Элемент списка */
.multiselect-option {
    display: flex;
    align-items: center;
    padding: 12px 16px;
    font-size: var(--font-size-paragraph);
    border-bottom: 1px solid #eef2f6;
    color: var(--color-label);
    background-color: #fff;
    cursor: pointer;
    transition: background-color 0.15s, padding-left 0.2s ease;
}

.multiselect-option:hover {
    background-color: #e8f4ff;
    padding-left: 20px; /* лёгкий эффект движения */
}

.multiselect-option:last-child {
    border-bottom: none;
}

/* Чекбоксы */
.multiselect-checkbox {
    accent-color: var(--color-focus-border);
    width: var(--checkbox-size);
    height: var(--checkbox-size);
    margin-right: 12px;
    flex-shrink: 0;
    cursor: pointer;
    transition: transform 0.15s ease;
}

.multiselect-checkbox:checked {
    transform: scale(1.1);
}

/* Текст внутри опции */
.multiselect-option label {
    font-size: var(--font-size-paragraph);
    line-height: 1.4;
    cursor: pointer;
    color: var(--color-label);
}

/* Добавим плавное раскрытие списка, если он действительно "выпадает" */
.multiselect-options-container {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transition: max-height 0.25s ease, opacity 0.25s ease;
}

.multiselect.open .multiselect-options-container {
    max-height: 400px; /* можно регулировать */
    opacity: 1;
}

/* ======================================= */
/* 4. КНОПКА И ОШИБКИ */
/* ======================================= */

#submit-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    height: var(--submit-btn-height);
    background-color: var(--color-submit-btn-bg); 
    color: var(--color-submit-btn-text);
    border: none;
    border-radius: var(--border-radius-input);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-bold);
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 4px 10px rgba(34, 158, 217, 0.4);

    width: calc(100% - var(--padding-sides) * 2); 
    margin: 0 var(--padding-sides) 30px var(--padding-sides); 
}

#submit-btn:hover {
    background-color: #1a8ed2; 
}

#submit-btn span {
    display: inline-flex;
    margin-right: 10px;
}

#submit-btn svg {
    fill: var(--color-submit-btn-text);
    height: 18px;
    width: 18px;
}

.button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background-color: var(--color-submit-btn-bg);
    color: var(--color-submit-btn-text);
    border: none;
    border-radius: var(--border-radius-input);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-bold);
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s, transform 0.1s;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 4px 10px rgba(34, 158, 217, 0.4);
    padding: 10px 22px; /* регулирует высоту и ширину */
    margin: 8px;
    height: auto;
    width: auto; /* не растягивается */
    min-width: 140px; /* чтобы не была слишком узкая */
}

.button:hover {
    background-color: #1a8ed2;
    transform: translateY(-1px);
}

.button:active {
    background-color: #1a8ed2;
    transform: translateY(0);
    box-shadow: 0 2px 5px rgba(34, 158, 217, 0.3);
}

.button svg {
    fill: var(--color-submit-btn-text);
    height: 18px;
    width: 18px;
    margin-right: 8px;
}

.button--secondary {
    background-color: #ffffff;
    color: var(--color-focus-border);
    border: 1px solid var(--color-focus-border);
    box-shadow: none;
}

.button--secondary:hover {
    background-color: #ebf6ff;
}

#fields-container {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-top: 10px;
  }

  .input-group {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .input-group textarea {
    flex: 1;
    padding: 10px;
    border: 1px solid #cfd8e6;
    border-radius: 8px;
    font-size: 14px;
    resize: vertical;
    min-height: 38px;
  }

  .remove-btn {
    background-color: #ff4d4d;
    border: none;
    color: #fff;
    border-radius: 6px;
    font-weight: bold;
    width: 32px;
    height: 32px;
    cursor: pointer;
    transition: background-color 0.2s ease;
  }

  .remove-btn:hover {
    background-color: #e13c3c;
  }

  .add-btn {
    margin-top: 14px;
    background-color: #229ED9;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 16px;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s ease;
  }

  .add-btn:hover {
    background-color: #1a8ed2;
  }

/* Сообщения об ошибке */
.error-field-0 {
    font-size: var(--font-size-error);
    color: var(--color-error);
    margin-top: 8px;
    padding-left: 5px;
}

.error-hidden {
    display: none;
}

.n8n-link {
  display: none !important;
}

