  box-shadow: 0 0 2px rgba(0, 0, 0, 0.2); /* лёгкая тень вместо толстой рамки */
}

.inputs-wrapper {
    margin: 30px var(--padding-sides) 20px var(--padding-sides);
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 24px; /* равномерные промежутки между группами полей */
}

.form-label {
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-bold);
    margin-bottom: 6px; /* меньшее расстояние между label и полем */
    color: var(--color-label);
}

.multiselect {
    position: relative;
    border: 1px solid var(--color-input-border);
    border-radius: var(--border-radius-input);
    background-color: #ffffff;
    box-shadow: 0 3px 8px rgba(34, 158, 217, 0.1);
    overflow: hidden;
    transition: all 0.2s ease;
}

.multiselect:hover {
    border-color: var(--color-focus-border);
    box-shadow: 0 4px 12px rgba(34, 158, 217, 0.15);
}

/* Вариант открытого списка — если у тебя есть класс .open */
.multiselect.open {
    border-color: var(--color-focus-border);
    box-shadow: 0 6px 16px rgba(34, 158, 217, 0.2);
}

/* Элемент списка */
.multiselect-option {
    display: flex;
    align-items: center;
    padding: 12px 16px;
    font-size: var(--font-size-paragraph);
    border-bottom: 1px solid #eef2f6;
    color: var(--color-label);
    background-color: #fff;
    cursor: pointer;
    transition: background-color 0.15s, padding-left 0.2s ease;
}

.multiselect-option:hover {
    background-color: #e8f4ff;
    padding-left: 20px; /* лёгкий эффект движения */
}

.multiselect-option:last-child {
    border-bottom: none;
}

/* Чекбоксы */
.multiselect-checkbox {
    accent-color: var(--color-focus-border);
    width: var(--checkbox-size);
    height: var(--checkbox-size);
    margin-right: 12px;
    flex-shrink: 0;
    cursor: pointer;
    transition: transform 0.15s ease;
}

.multiselect-checkbox:checked {
    transform: scale(1.1);
}

/* Текст внутри опции */
.multiselect-option label {
    font-size: var(--font-size-paragraph);
    line-height: 1.4;
    cursor: pointer;
    color: var(--color-label);
}

/* Добавим плавное раскрытие списка, если он действительно "выпадает" */
.multiselect-options-container {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transition: max-height 0.25s ease, opacity 0.25s ease;
}

.multiselect.open .multiselect-options-container {
    max-height: 400px; /* можно регулировать */
    opacity: 1;
}

/* ======================================= */
/* 4. КНОПКА И ОШИБКИ */
/* ======================================= */

#submit-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    height: var(--submit-btn-height);
    background-color: var(--color-submit-btn-bg); 
    color: var(--color-submit-btn-text);
    border: none;
    border-radius: var(--border-radius-input);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-bold);
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 4px 10px rgba(34, 158, 217, 0.4);

    width: calc(100% - var(--padding-sides) * 2); 
    margin: 0 var(--padding-sides) 30px var(--padding-sides); 
}

#submit-btn:hover {
    background-color: #1a8ed2; 
}

#submit-btn span {
    display: inline-flex;
    margin-right: 10px;
}

#submit-btn svg {
    fill: var(--color-submit-btn-text);
    height: 18px;
    width: 18px;
}

.button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background-color: var(--color-submit-btn-bg);
    color: var(--color-submit-btn-text);
    border: none;
    border-radius: var(--border-radius-input);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-bold);
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s, transform 0.1s;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 4px 10px rgba(34, 158, 217, 0.4);
    padding: 10px 22px; /* регулирует высоту и ширину */
    margin: 8px;
    height: auto;
    width: auto; /* не растягивается */
    min-width: 140px; /* чтобы не была слишком узкая */
}

.button:hover {
    background-color: #1a8ed2;
    transform: translateY(-1px);
}

.button:active {
    background-color: #1a8ed2;
    transform: translateY(0);
    box-shadow: 0 2px 5px rgba(34, 158, 217, 0.3);
}

.button svg {
    fill: var(--color-submit-btn-text);
    height: 18px;
    width: 18px;
    margin-right: 8px;
}

.button--secondary {
    background-color: #ffffff;
    color: var(--color-focus-border);
    border: 1px solid var(--color-focus-border);
    box-shadow: none;
}

.button--secondary:hover {
    background-color: #ebf6ff;
}

#fields-container {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-top: 10px;
  }

  .input-group {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .input-group textarea {
    flex: 1;
    padding: 10px;
    border: 1px solid #cfd8e6;
    border-radius: 8px;
    font-size: 14px;
    resize: vertical;
    min-height: 38px;
  }

  .remove-btn {
    background-color: #ff4d4d;
    border: none;
    color: #fff;
    border-radius: 6px;
    font-weight: bold;
    width: 32px;
    height: 32px;
    cursor: pointer;
    transition: background-color 0.2s ease;
  }

  .remove-btn:hover {
    background-color: #e13c3c;
  }

  .add-btn {
    margin-top: 14px;
    background-color: #229ED9;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 16px;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s ease;
  }

  .add-btn:hover {
    background-color: #1a8ed2;
  }

/* Сообщения об ошибке */
.error-field-0 {
    font-size: var(--font-size-error);
    color: var(--color-error);
    margin-top: 8px;
    padding-left: 5px;
}

.error-hidden {
    display: none;
}

.n8n-link {
  display: none !important;
}

parameters.jsonOutput:
=={{
[
    {
      "fieldLabel": "Name",
      "requiredField": true
    },
    {
      "fieldLabel": "Platform",
      "requiredField": true
    },
    {
      "fieldLabel": "Default tone-of-voice",
      "fieldType": "dropdown",
      "fieldOptions": {
        "values": $('Get tov-s1').all().map(item => ({ "option": item.json.profile_name }))
      }
    },
    {
      "fieldLabel": "rules_data",
      "fieldType": "hiddenField",
      "fieldValue": JSON.stringify({
        existingRules: $("Get tov-rules").all().map(i => i.json).filter(i => i.name).map(i => ({ id: i.id, name: i.name })),
        availableTovs: $("Get tov-s1").all().map(i => i.json).filter(i => i.profile_name).map(i => ({ id: i.id, name: i.profile_name })),
        contentTypes: $("Data").item.json.statuses.content_type || []
      })
    },
    {
      "fieldLabel": "tov_rules",
      "fieldType": "hiddenField",
      "fieldValue": "[]"
    },
    {
      "fieldLabel": "new_tovs",
      "fieldType": "hiddenField",
      "fieldValue": "[]"
    },
    {
      "fieldType": "html",
      // Вся подготовка данных происходит "на лету" прямо внутри этой строки
      "html": "<label class="form-label">Associated ToV Rules</label>

<div style="border: 1px solid #d0d7e3; border-radius: 10px; padding: 12px; margin-top: 6px;">
  <div style="display:flex; gap:10px; align-items:center; margin-bottom:10px;">
    <select id="existing-rule-selector" class="form-input" style="flex:1; padding:8px; border-radius:6px; border:1px solid #cfd8e6;"></select>
    <button type="button" id="add-existing-rule-btn" style="padding:8px 12px; border-radius:6px; border:none; background:#229ED9; color:#fff; cursor:pointer;">Add</button>
  </div>

  <div id="selected-rules-container" style="display:flex; flex-wrap:wrap; gap:8px; margin-bottom:8px;"></div>

  <hr style="border:none; border-top:1px solid #eef2f6; margin:12px 0;" />

  <div>
    <label style="font-weight:600; display:block; margin-bottom:8px;">Create New Rule</label>
    <div id="new-rules-container" style="display:flex; flex-direction:column; gap:10px;"></div>
    <button type="button" id="create-new-rule-btn" style="margin-top:8px; padding:8px 12px; border-radius:6px; border:none; background:#1a8ed2; color:#fff; cursor:pointer;">+ Create rule</button>
  </div>
</div>

<script>
(function () {
  // CONFIG: names of hidden fields
  const SOURCE_FIELD = 'field-3'; // must contain JSON with existingRules, availableTovs, contentTypes
  const OUT_EXISTING_FIELD = 'field-4'; // will receive JSON array of selected existing rule ids
  const OUT_NEW_FIELD = 'field-5';      // will receive JSON array of new rules objects

  function safeParse(v){ try { return v ? JSON.parse(v) : null } catch(e){ return null } }
  function escapeHtml(s){ return String(s||'').replace(/[&<>\"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":"&#39;"}[m])); }

  const srcEl = document.querySelector(`[name="${SOURCE_FIELD}"]`);
  const outExistingEl = document.querySelector(`[name="${OUT_EXISTING_FIELD}"]`);
  const outNewEl = document.querySelector(`[name="${OUT_NEW_FIELD}"]`);

  const raw = srcEl ? srcEl.value : null;
  const parsed = safeParse(raw) || {};

  const existingRules = Array.isArray(parsed.existingRules) ? parsed.existingRules : [];
  const availableTovs = Array.isArray(parsed.availableTovs) ? parsed.availableTovs : [];
  const contentTypes = Array.isArray(parsed.contentTypes) ? parsed.contentTypes : [];

  // UI refs
  const existingSelector = document.getElementById('existing-rule-selector');
  const addExistingBtn = document.getElementById('add-existing-rule-btn');
  const selectedContainer = document.getElementById('selected-rules-container');

  const newRulesContainer = document.getElementById('new-rules-container');
  const createNewBtn = document.getElementById('create-new-rule-btn');

  // Fill existingRules select (these are the rules that already exist in DB)
  function fillExistingRulesSelect(){
    existingSelector.innerHTML = '';
    if (existingRules.length === 0){
      const opt = document.createElement('option');
      opt.textContent = 'No existing rules';
      opt.disabled = true;
      opt.selected = true;
      existingSelector.appendChild(opt);
      addExistingBtn.disabled = true;
      addExistingBtn.style.opacity = 0.6;
    } else {
      addExistingBtn.disabled = false;
      addExistingBtn.style.opacity = 1;
      const placeholder = document.createElement('option');
      placeholder.value = '';
      placeholder.textContent = 'Choose existing rule...';
      placeholder.disabled = true;
      placeholder.selected = true;
      existingSelector.appendChild(placeholder);
      existingRules.forEach(r => {
        const o = document.createElement('option');
        o.value = r.id;
        o.textContent = r.name || r.id;
        existingSelector.appendChild(o);
      });
    }
  }

  // Add tag for selected existing rule
  function addExistingTag(id, name){
    if (!id) return;
    if (selectedContainer.querySelector(`[data-id="${id}"]`)) return; // prevent duplicates
    const wrap = document.createElement('div');
    wrap.dataset.id = id;
    wrap.style = "display:inline-flex;align-items:center;gap:8px;padding:6px 10px;background:#eef6ff;border-radius:14px;margin:4px;";
    const span = document.createElement('span'); span.textContent = name;
    const btn = document.createElement('button'); btn.type='button'; btn.textContent='×';
    btn.style = 'border:none;background:transparent;cursor:pointer;font-weight:bold;';
    btn.onclick = () => { wrap.remove(); syncExistingOutput(); };
    wrap.appendChild(span); wrap.appendChild(btn);
    selectedContainer.appendChild(wrap);
    syncExistingOutput();
  }

  // Sync selected existing ids to hidden field
  function syncExistingOutput(){
    const ids = Array.from(selectedContainer.querySelectorAll('[data-id]')).map(el => el.dataset.id);
    if (outExistingEl) outExistingEl.value = JSON.stringify(ids);
  }

  // Create new rule block (UI)
  function createNewRuleBlock(prefill){
    const b = document.createElement('div');
    b.className = 'new-rule-form';
    b.style = 'border:1px dashed #dbe9f6;padding:10px;border-radius:8px;display:flex;flex-direction:column;gap:8px;background:#fcfeff;position:relative;';

    // build options for tov and content type
    const tovOptions = [''].concat(availableTovs || []).map(t => `<option value="${escapeHtml(t.id)}">${escapeHtml(t.name || t.id)}</option>`).join('');
    const ctOptions = [''].concat(contentTypes || []).map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c || '-- content type --')}</option>`).join('');

    b.innerHTML = `
      <button type="button" class="remove-new-rule" aria-label="remove" style="position:absolute;right:8px;top:8px;border:none;background:transparent;cursor:pointer;font-size:18px;">×</button>
      <input data-key="name" class="form-input" placeholder="Rule name (optional)" style="padding:8px;border-radius:6px;border:1px solid #cfd8e6;" value="${prefill && prefill.name ? escapeHtml(prefill.name) : ''}" />
      <select data-key="tov_id" class="form-input" style="padding:8px;border-radius:6px;border:1px solid #cfd8e6;">${tovOptions}</select>
      <select data-key="content_type" class="form-input" style="padding:8px;border-radius:6px;border:1px solid #cfd8e6;">${ctOptions}</select>
      <input data-key="keywords" class="form-input" placeholder="keywords (comma separated)" style="padding:8px;border-radius:6px;border:1px solid #cfd8e6;" value="${prefill && prefill.keywords ? escapeHtml((prefill.keywords||[]).join(',')) : ''}" />
      <input data-key="priority" type="number" min="0" max="100" class="form-input" placeholder="priority (0-100)" style="padding:8px;border-radius:6px;border:1px solid #cfd8e6;" value="${prefill && typeof prefill.priority !== 'undefined' ? escapeHtml(String(prefill.priority)) : '0'}" />
    `;

    // handlers
    b.querySelector('.remove-new-rule').addEventListener('click', () => { b.remove(); syncNewOutput(); });
    Array.from(b.querySelectorAll('input, select')).forEach(i => i.addEventListener('input', syncNewOutput));

    newRulesContainer.appendChild(b);
    syncNewOutput();
    return b;
  }

  // Sync new rules to hidden field
  function syncNewOutput(){
    const blocks = newRulesContainer.querySelectorAll('.new-rule-form');
    const arr = Array.from(blocks).map(b => {
      const name = (b.querySelector('[data-key="name"]').value || '').trim() || null;
      const tov_id = (b.querySelector('[data-key="tov_id"]').value || '').trim() || null;
      const content_type = (b.querySelector('[data-key="content_type"]').value || '').trim() || null;
      const keywordsRaw = (b.querySelector('[data-key="keywords"]').value || '').trim();
      const keywords = keywordsRaw ? keywordsRaw.split(',').map(s=>s.trim()).filter(Boolean) : null;
      let priorityRaw = b.querySelector('[data-key="priority"]').value;
      let priority = null;
      if (priorityRaw !== undefined && priorityRaw !== null && priorityRaw !== '') {
        priority = parseInt(priorityRaw, 10);
        if (Number.isNaN(priority)) priority = 0;
        if (priority < 0) priority = 0;
        if (priority > 100) priority = 100;
      }
      return { name, tov_id, content_type, keywords, priority: priority === null ? 0 : priority };
    });
    if (outNewEl) outNewEl.value = JSON.stringify(arr.length ? arr : []);
  }

  // initial fill
  fillExistingRulesSelect();

  // prefill selected existing if any output already has values
  if (outExistingEl) {
    const existingPre = safeParse(outExistingEl.value) || [];
    existingPre.forEach(id => {
      const r = existingRules.find(x => String(x.id) === String(id));
      if (r) addExistingTag(id, r.name);
    });
  }

  // prefill new rules if output has values
  if (outNewEl) {
    const newPre = safeParse(outNewEl.value) || [];
    newPre.forEach(p => createNewRuleBlock(p));
  }

  // handlers
  addExistingBtn.addEventListener('click', () => {
    const id = existingSelector.value;
    if (!id) return;
    const r = existingRules.find(x => String(x.id) === String(id));
    addExistingTag(id, r ? r.name : id);
  });

  createNewBtn.addEventListener('click', () => createNewRuleBlock());

  // ensure sync on submit
  const form = document.querySelector('form');
  if (form) form.addEventListener('submit', () => { syncExistingOutput(); syncNewOutput(); }, true);

  // final sync initial
  syncExistingOutput();
  syncNewOutput();

})();
</script>"
    }
]
}}

