  },
  {
    "fieldLabel": "Default tone-of-voice",
    "fieldType": "dropdown",
    "fieldOptions": {
      "values": $('Get tov-s2').all().map(item => ({ "option": item.json.profile_name }))
    }
  },
  {
    "fieldLabel": "rules_data",
    "fieldType": "hiddenField",
    "fieldValue": JSON.stringify({
      existingRules: $("Get tov-rules1").all().map(i => i.json).filter(i => i.name).map(i => ({ id: i.id, name: i.name })),
      availableTovs: $("Get tov-s2").all().map(i => i.json).filter(i => i.profile_name).map(i => ({ id: i.id, name: i.profile_name })),
      contentTypes: $("Data").item.json.statuses.content_type || []
    })
  },
  {
    "fieldLabel": "tov_rules",
    "fieldType": "hiddenField",
    "fieldValue": JSON.stringify(($input.item.json.tov_rules || []).map(r => r.id))
  },
  {
    "fieldLabel": "new_tovs",
    "fieldType": "hiddenField",
    "fieldValue": "[]"
  },
  {
    "fieldLabel": "channel_data",
    "fieldType": "hiddenField",
    "fieldValue": JSON.stringify($input.item.json)
  },
  {
    fieldType: "html",
    html: "<label class="form-label">Associated ToV Rules</label>
<div style="border: 1px solid #d0d7e3; border-radius: 10px; padding: 12px; margin-top: 6px;">
  <div style="display:flex; gap:10px; align-items:center; margin-bottom:10px;">
    <select id="existing-rule-selector" class="form-input" style="flex:1; padding:8px; border-radius:6px; border:1px solid #cfd8e6;"></select>
    <button type="button" id="add-existing-rule-btn" style="padding:8px 12px; border-radius:6px; border:none; background:#229ED9; color:#fff; cursor:pointer;">Add</button>
  </div>

  <div id="selected-rules-container" style="display:flex; flex-wrap:wrap; gap:8px; margin-bottom:8px;"></div>

  <hr style="border:none; border-top:1px solid #eef2f6; margin:12px 0;" />

  <div>
    <label style="font-weight:600; display:block; margin-bottom:8px;">Create New Rule</label>
    <div id="new-rules-container" style="display:flex; flex-direction:column; gap:10px;"></div>
    <button type="button" id="create-new-rule-btn" style="margin-top:8px; padding:8px 12px; border-radius:6px; border:none; background:#1a8ed2; color:#fff; cursor:pointer;">+ Create rule</button>
  </div>
</div>
<script>
(function waitForForm() {
  const selector = document.getElementById('existing-rule-selector');
  if (!selector) {
    return setTimeout(waitForForm, 200); // форма ещё не готова
  }

  // Теперь всё DOM дерево доступно — можно выполнять основной код
  initChannelForm();
})();

function initChannelForm() {
  const safeParse = v => { try { return v ? JSON.parse(v) : null } catch { return null; } };
  const escapeHtml = s => String(s||'').replace(/[&<>"']/g, m => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;' }[m]));

  // --- поля
  const channelEl = document.querySelector('#field-6');
  const srcEl = document.querySelector('#field-3');
  const outExistingEl = document.querySelector('#field-4');
  const outNewEl = document.querySelector('#field-5');

  const selector = document.getElementById('existing-rule-selector');
  const addBtn = document.getElementById('add-existing-rule-btn');
  const selectedContainer = document.getElementById('selected-rules-container');
  const newRulesContainer = document.getElementById('new-rules-container');
  const createNewBtn = document.getElementById('create-new-rule-btn');

  // --- загрузка данных
  const channelData = safeParse(channelEl?.value) || {};
  const rulesData = safeParse(srcEl?.value) || {};
  const existingRules = rulesData.existingRules || [];
  const availableTovs = rulesData.availableTovs || [];
  const contentTypes = rulesData.contentTypes || [];

  // --- базовые поля
  const nameEl = document.querySelector('#field-0');
  const platformEl = document.querySelector('#field-1');
  const tovEl = document.querySelector('#field-2');

  if (nameEl) nameEl.value = channelData.name || '';
  if (platformEl) platformEl.value = channelData.platform || '';
  if (tovEl && channelData.default_tov) {
    const match = Array.from(tovEl.options).find(o => o.value === channelData.default_tov.profile_name);
    if (match) match.selected = true;
  }

  // --- заполнение списка правил
  selector.innerHTML = '<option value="">Choose existing rule...</option>';
  existingRules.forEach(r => {
    const o = document.createElement('option');
    o.value = r.id;
    o.textContent = r.name;
    selector.appendChild(o);
  });

  // --- выбранные правила
  const preSelected = (channelData.tov_rules || []).map(r => r.id);
  preSelected.forEach(id => {
    const rule = existingRules.find(x => x.id === id);
    if (rule) addExistingTag(rule.id, rule.name);
  });
  syncExistingOutput();

  // --- кнопки
  addBtn.addEventListener('click', () => {
    const id = selector.value;
    if (!id) return;
    const r = existingRules.find(x => x.id === id);
    addExistingTag(r.id, r.name);
  });

  createNewBtn.addEventListener('click', () => createNewRuleBlock());

  // --- helpers
  function addExistingTag(id, name) {
    if (selectedContainer.querySelector(`[data-id="${id}"]`)) return;
    const tag = document.createElement('div');
    tag.dataset.id = id;
    tag.style = 'display:inline-flex;align-items:center;gap:6px;padding:6px 10px;background:#eef6ff;border-radius:14px;';
    tag.textContent = name;
    const btn = document.createElement('button');
    btn.textContent = '×';
    btn.style = 'border:none;background:transparent;cursor:pointer;font-weight:bold;';
    btn.onclick = () => { tag.remove(); syncExistingOutput(); };
    tag.appendChild(btn);
    selectedContainer.appendChild(tag);
  }

  function syncExistingOutput() {
    const ids = Array.from(selectedContainer.querySelectorAll('[data-id]')).map(el => el.dataset.id);
    if (outExistingEl) outExistingEl.value = JSON.stringify(ids);
  }

  function createNewRuleBlock(prefill) {
    const b = document.createElement('div');
    b.className = 'new-rule-form';
    b.style = 'border:1px dashed #dbe9f6;padding:10px;border-radius:8px;display:flex;flex-direction:column;gap:8px;background:#fcfeff;position:relative;';
    const tovOptions = [''].concat(availableTovs).map(t => `<option value="${escapeHtml(t.id)}">${escapeHtml(t.name)}</option>`).join('');
    const ctOptions = [''].concat(contentTypes).map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');
    b.innerHTML = `
      <button type="button" class="remove-new-rule" style="position:absolute;right:8px;top:8px;border:none;background:transparent;cursor:pointer;font-size:18px;">×</button>
      <input data-key="name" placeholder="Rule name" class="form-input" style="padding:8px;border:1px solid #cfd8e6;border-radius:6px;" value="${prefill?.name||''}"/>
      <select data-key="tov_id" class="form-input" style="padding:8px;border:1px solid #cfd8e6;border-radius:6px;">${tovOptions}</select>
      <select data-key="content_type" class="form-input" style="padding:8px;border:1px solid #cfd8e6;border-radius:6px;">${ctOptions}</select>
      <input data-key="keywords" placeholder="keywords (comma separated)" class="form-input" style="padding:8px;border:1px solid #cfd8e6;border-radius:6px;" value="${(prefill?.keywords||[]).join(',')}"/>
      <input data-key="priority" type="number" min="0" max="100" placeholder="priority (0-100)" class="form-input" style="padding:8px;border:1px solid #cfd8e6;border-radius:6px;" value="${prefill?.priority||0}"/>
    `;
    b.querySelector('.remove-new-rule').addEventListener('click', () => { b.remove(); syncNewOutput(); });
    b.querySelectorAll('input, select').forEach(el => el.addEventListener('input', syncNewOutput));
    newRulesContainer.appendChild(b);
    syncNewOutput();
  }

  function syncNewOutput() {
    const arr = Array.from(newRulesContainer.querySelectorAll('.new-rule-form')).map(b => ({
      name: b.querySelector('[data-key="name"]').value,
      tov_id: b.querySelector('[data-key="tov_id"]').value,
      content_type: b.querySelector('[data-key="content_type"]').value,
      keywords: b.querySelector('[data-key="keywords"]').value.split(',').map(s=>s.trim()).filter(Boolean),
      priority: parseInt(b.querySelector('[data-key="priority"]').value) || 0
    }));
    if (outNewEl) outNewEl.value = JSON.stringify(arr);
  }

  console.log('✅ Prefilled channel:', channelData);
}
</script>"
  }
]
}}

