	--color-background: #f1f6fb;
	--color-header-bg: #229ED9; /* Telegram Blue */
	--color-header-text: #ffffff; /* Белый цвет */
	--color-card-bg: #ffffff;
	--color-card-shadow: rgba(34, 158, 217, 0.15);
	--color-label: #2b2b2b;
	--color-details: #5b6c7b;
	--color-input-border: #cfd8e6;
	--color-focus-border: #229ED9; 
	--color-submit-btn-bg: #229ED9;
	--color-submit-btn-text: #ffffff;
	--color-error: #ea1f30;

