parameters.jsCode:
// --- Получаем данные из нужных нод
const oldChannel = $('Get channel').first().json; // старый канал до редактирования
const editResponse = $('Send wait for response edit channe').first().json; // данные из формы

// --- Извлекаем старые правила
let oldRules = oldChannel.tov_rules || [];

// --- Извлекаем новые (текущие) правила
let tovRules = editResponse.data?.tov_rules;
let newRulesRaw = editResponse.data?.new_tovs;

// --- Попробуем распарсить, если пришло строкой
if (typeof tovRules === 'string') {
  try { tovRules = JSON.parse(tovRules); } catch { tovRules = []; }
}
if (typeof newRulesRaw === 'string') {
  try { newRulesRaw = JSON.parse(newRulesRaw); } catch { newRulesRaw = []; }
}

// --- Если это не массивы — сбрасываем
if (!Array.isArray(tovRules)) tovRules = [];
if (!Array.isArray(newRulesRaw)) newRulesRaw = [];

// --- Нормализуем ID (т.к. иногда tov_rules может быть [{id}, ...] или просто ["uuid", ...])
const oldIds = oldRules.map(r => typeof r === 'string' ? r : r.id);
const newIds = tovRules.map(r => typeof r === 'string' ? r : r.id);

// --- Определяем изменения
const addedRules = newIds.filter(id => !oldIds.includes(id)).map(id => ({ id }));
const removedRules = oldIds.filter(id => !newIds.includes(id)).map(id => ({ id }));

// --- Возвращаем итоговый объект
return {
  addedRules,
  removedRules,
  newRules: newRulesRaw,
  channel_id: oldChannel.id // полезно, если дальше ты хочешь использовать в SQL
};

parameters.query:
DO $$
DECLARE
  channel_id uuid := '{{ $("Add channel").item.json.id }}'::uuid;
  tov_rules JSONB := '{{ $("Send wait for response add channel2").item.json.data.tov_rules }}'::jsonb;
  new_rules JSONB := '{{ $("Send wait for response add channel2").item.json.data.new_tovs }}'::jsonb;
  rule JSONB;
  new_rule JSONB;
  rule_id uuid;
  keywords_arr text[];
BEGIN
  -- если tov_rules — массив, создаём связи с уже существующими правилами
  IF jsonb_typeof(tov_rules) = 'array' THEN
    FOR rule IN SELECT jsonb_array_elements(tov_rules)
    LOOP
      INSERT INTO tov_rule_channels(rule_id, channel_id)
      VALUES ((rule->>'id')::uuid, channel_id)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  -- если new_rules — массив, создаём новые правила и связи
  IF jsonb_typeof(new_rules) = 'array' THEN
    FOR new_rule IN SELECT jsonb_array_elements(new_rules)
    LOOP
      -- безопасно достаём keywords
      IF jsonb_typeof(new_rule->'keywords') = 'array' THEN
        keywords_arr := ARRAY(
          SELECT jsonb_array_elements_text(new_rule->'keywords')
        );
      ELSE
        keywords_arr := ARRAY[]::text[];
      END IF;

      -- создаём новое правило
      INSERT INTO tov_rules(name, tov_id, content_type, keywords, priority)
      VALUES (
        new_rule->>'name',
        (new_rule->>'tov_id')::uuid,
        new_rule->>'content_type',
        keywords_arr,
        COALESCE((new_rule->>'priority')::int, 0)
      )
      RETURNING id INTO rule_id;

      -- создаём связь с каналом
      INSERT INTO tov_rule_channels(rule_id, channel_id)
      VALUES (rule_id, channel_id);
    END LOOP;
  END IF;
END $$;

